# coding: utf-8
from lesson_authoring import entry as E
B=[['拉丁 orare','正式讲话、恳求、祈祷']]
W=[
E('orator','英 /ˈɒrətə/；美 /ˈɔrətər/','演说家；善于公开讲话的人','面对一群人，把话讲得有结构、有力量，让听众愿意跟着想。','来自盎格鲁法语 oratour 及拉丁 orator，接 orare 正式讲话。',B+[['拉丁 orator → 法语 oratour／英语 orator','公开讲话者、为某事辩说的人']],'a gifted orator 是有演讲天赋的人。它通常比 speaker 更突出正式场合和表达能力；随口说了几句话的人一般不因此称为 orator。','a gifted orator；a powerful orator；a political orator。','speaker 可以是任何发言者，也可以是扬声器；orator 通常是善于或专事公开演说的人。',('She became known as a powerful orator.','她以富有感染力的演讲才能而闻名。'),('The orator held the audience’s attention without raising his voice.','这位演说家没有提高嗓门，却牢牢吸引了听众。'),sources=['https://www.etymonline.com/word/orator','https://en.wiktionary.org/wiki/orator']),
E('oration','英 /ɒˈreɪʃən/；美 /ɔˈreɪʃən/','正式演说；致辞','把一次庄重、成篇的公开发言看作一个完整作品。','来自拉丁 oratio／oration-，接 orare；不是由英语 orate 的现代演说义简单加 -ion 才形成。',B+[['拉丁 oratio／oration- → 英语 oration','讲话、祈祷 → 正式演说']],'a funeral oration 是葬礼上的悼词；deliver an oration 是发表正式演说。它常有仪式感，或带文学色彩，不是普通会议里的每次发言。','deliver an oration；a funeral oration；a stirring oration。','speech 很通用，oration 更庄重、修辞感更强；presentation 常包含讲解展示，不必有这种演说气氛。',('She delivered a moving oration at the memorial service.','她在追悼会上发表了感人的悼词。'),('The book includes several of his most influential orations.','这本书收录了他几篇影响最大的演说。'),sources=['https://www.etymonline.com/word/oration','https://en.wiktionary.org/wiki/oration']),
E('oratory','英 /ˈɒrətəri/；美 /ˈɔrəˌtɔri/','演讲术；雄辩；小祈祷堂','一条支线是面对人群把话说好，另一条是专门向神祈祷的地方。','演讲义接拉丁 ars oratoria 演讲之术；祈祷堂义接晚期拉丁 oratorium，经法语借入，是同族的另一条路线。',B+[['拉丁 ars oratoria → 英语 oratory（演讲义）','公开演说的艺术、能力'],['并行：晚期拉丁 oratorium → 法语／英语 oratory（场所义）','祈祷场所、小祈祷堂']],'powerful oratory 是有感染力的演说；an oratory 则可能是一间小祈祷堂。演讲义通常不可数，建筑义可数；不能把小教堂硬解释成演讲发展后的比喻。','the art of oratory；political oratory；powerful oratory；a private oratory。','orator 是人，oration 是一次演说，oratory 多说能力或艺术；另有独立借入的祈祷堂义。',('Her oratory inspired the crowd to act.','她的演说激励人群行动起来。'),('A small oratory stood beside the main chapel.','主礼拜堂旁有一间小祈祷堂。'),sources=['https://www.etymonline.com/word/oratory','https://en.wiktionary.org/wiki/oratory']),
E('oratorical','英 /ˌɒrəˈtɒrɪkəl/；美 /ˌɔrəˈtɔrɪkəl/','演说的；富于演说技巧的','关注一个人讲话时怎样组织词句、推动情绪和说服听众。','可由 orator／oratory 配 -ical 理解，也有拉丁 oratorius 借入分析；不是普通口头表达的通称。',B+[['拉丁 oratorius 与英语 orator／oratory 词族','演讲者、演讲艺术'],['英语 oratorical','与正式演说及技巧有关的']],'oratorical skills 是演说技巧，oratorical flourishes 是有修辞装饰、气势的说法。它既能赞赏，也可能暗示话说得漂亮但内容不够。','oratorical skills；oratorical ability；an oratorical flourish。','oral 是口头的，oratorical 是演说方面的。口头报一个地址是 oral communication，通常谈不上 oratorical performance。',('The debate gave her a chance to display her oratorical skills.','这场辩论让她有机会展现演说技巧。'),('The speech relied more on oratorical flourishes than on evidence.','这篇演说更多依靠漂亮的修辞，而非证据。'),sources=['https://www.etymonline.com/word/oratorical','https://en.wiktionary.org/wiki/oratorical']),
E('orate','英 /ɔːˈreɪt/；美 /ˈɔreɪt/ 或 /ɔˈreɪt/','发表正式演说；高谈阔论','摆开演说架势讲一大段，有时旁人已经觉得他讲得太起劲了。','早期形式接拉丁 oratus；现代正式演说义又与从 oration 逆构有关，应分开看。',B+[['拉丁 oratus → 早期英语 orate','祈祷、恳求'],['后来的 oration → orate（演说义）','作正式演说，常带调侃或贬意']],'He began to orate 容易让人想到某人开始一本正经地长篇发言。它不是 say 的普通替代词，写人物时常带一点揶揄。','orate about a subject；orate to an audience；begin to orate。','speak 是中性说话；orate 常突出正式腔调，甚至演说过头。用它描述朋友讲话可能是在开玩笑。',('He began to orate about the importance of punctuality.','他开始一本正经地大谈守时的重要性。'),('She could orate for an hour without consulting her notes.','她可以不看讲稿连续演说一个小时。'),sources=['https://www.etymonline.com/word/orate','https://en.wiktionary.org/wiki/orate'])]
